<script setup>
import {computed,ref,watch} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useAuthStore} from '../stores/auth'
import {useMarketStore} from '../stores/market'
import {LOCATIONS} from '../data/seed'
import {action,money,notify} from '../lib/ui'
import Icon from '../components/Icon.vue'
import CampusMap from '../components/CampusMap.vue'
const auth=useAuthStore(),market=useMarketStore(),route=useRoute(),router=useRouter()
const selected=ref([]),locationId=ref('library'),note=ref(''),showMap=ref(false),busy=ref(false)
const cart=computed(()=>market.userCart(auth.user.id)),available=computed(()=>cart.value.filter(p=>p.status==='available'))
watch(()=>cart.value.map(p=>p.id).join(','),()=>{selected.value=selected.value.filter(id=>available.value.some(p=>p.id===id));if(!selected.value.length)selected.value=route.query.buy?available.value.filter(p=>p.id===route.query.buy).map(p=>p.id):available.value.map(p=>p.id)},{immediate:true})
const groups=computed(()=>Array.from(Map.groupBy(cart.value,p=>p.sellerId),([sellerId,items])=>({sellerId,name:items[0].sellerName,college:items[0].college,items})))
const chosen=computed(()=>cart.value.filter(p=>selected.value.includes(p.id)&&p.status==='available'))
const total=computed(()=>chosen.value.reduce((n,p)=>n+p.price,0))
function selectAll(event){selected.value=event.target.checked?available.value.map(p=>p.id):[]}
async function checkout(){busy.value=true;const result=await action(()=>market.createOrders(auth.user.id,chosen.value.map(p=>p.id),{locationId:locationId.value,note:note.value}));busy.value=false;if(result){notify(`已生成 ${result.length} 笔订单，去完成模拟付款吧`);router.push('/orders')}}
</script>
<template><div class="page-width inner-page"><div class="page-title"><span class="eyebrow">SAVED A PLACE IN YOUR HEART</span><h1>把心动，带回你的日常。</h1><p>购物车里装着的，是下一段美好的开始。</p></div><div v-if="cart.length" class="checkout-layout"><section><div class="cart-select-all"><label class="checkbox-label"><input type="checkbox" :checked="available.length>0&&selected.length===available.length" @change="selectAll"/>全选好物</label><span>共 {{cart.length}} 件闲置</span></div><div v-for="group in groups" :key="group.sellerId" class="panel cart-seller-group"><div class="cart-seller-header"><span class="avatar-dot">{{group.name.slice(-2)}}</span><strong>{{group.name}}的毕业清单</strong><span>{{group.college}}</span></div><div v-for="product in group.items" :key="product.id" class="cart-item"><input v-model="selected" type="checkbox" :value="product.id" :disabled="product.status!=='available'" :aria-label="`选择${product.title}`"/><RouterLink :to="`/product/${product.id}`"><img :src="product.images[0]" :alt="product.title"/></RouterLink><div class="cart-item-info"><RouterLink :to="`/product/${product.id}`">{{product.title}}</RouterLink><small>{{product.condition}} · 校园面交</small><span v-if="product.status!=='available'" class="tag muted">{{({reserved:'已被预订',sold:'已售出',offline:'已下架'})[product.status]}}</span></div><strong class="rose">¥{{money(product.price)}}</strong><button class="icon-button" @click="action(()=>market.removeFromCart(auth.user.id,product.id))" :aria-label="`移除${product.title}`"><Icon name="trash" :size="18"/></button></div></div></section><aside class="panel checkout-summary"><span class="eyebrow">YOUR NEXT CHAPTER</span><h2>心动清单</h2><div class="summary-line"><span>已选好物</span><strong>{{chosen.length}} 件</strong></div><div class="summary-line"><span>交接方式</span><strong>校内面交</strong></div><label for="cart-location">在哪里见面<select id="cart-location" v-model="locationId"><option v-for="place in LOCATIONS" :key="place.id" :value="place.id">{{place.name}}</option></select></label><button class="text-link" @click="showMap=true"><Icon name="pin" :size="15"/>在校园地图上选择</button><label for="cart-note">给卖家留句话<textarea id="cart-note" v-model="note" rows="3" maxlength="300" placeholder="例如：周三下课后方便交接吗？"/></label><div class="summary-total"><span>合计</span><strong><small>¥</small>{{money(total)}}</strong></div><button class="button primary large full" :disabled="!chosen.length||busy" @click="checkout">{{busy?'正在生成订单…':'下一步，生成订单'}}<Icon name="arrow" :size="18"/></button><p class="checkout-hint"><Icon name="info" :size="15"/>按卖家分别生成订单，下单后为你保留物品。支付仅为课堂模拟。</p></aside></div><div v-else class="panel empty-state"><Icon name="cart" :size="48"/><h2>这里还留着一点空位</h2><p>把喜欢的闲置放进来，慢慢挑选。</p><RouterLink to="/market" class="button primary">去发现心动好物<Icon name="arrow" :size="17"/></RouterLink></div><Teleport to="body"><div v-if="showMap" class="modal-overlay" @click.self="showMap=false"><section class="modal map-modal"><button class="modal-close icon-button" @click="showMap=false" aria-label="关闭地图"><Icon name="close"/></button><CampusMap v-model="locationId"/><button class="button primary map-confirm" @click="showMap=false">就约在这里<Icon name="check" :size="17"/></button></section></div></Teleport></div></template>
